import{_ as a,o as e,c as r,a2 as l}from"./chunks/framework.E8pQZ6KS.js";const u=JSON.parse('{"title":"数据结构与算法","description":"","frontmatter":{},"headers":[],"relativePath":"专业基础/数据结构与算法.md","filePath":"专业基础/数据结构与算法.md","lastUpdated":1792430298000}'),i={name:"专业基础/数据结构与算法.md"};function d(o,t,h,n,s,_){return e(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="数据结构与算法" tabindex="-1">数据结构与算法 <a class="header-anchor" href="#数据结构与算法" aria-label="Permalink to &quot;数据结构与算法&quot;">​</a></h1><blockquote><p>计算机专业的第一门「硬课」。校内第 2 学期开设（含课程设计）。对网安来说，它决定你能读懂漏洞利用代码、写出高效的安全工具。</p></blockquote><h2 id="为什么学" tabindex="-1">为什么学 <a class="header-anchor" href="#为什么学" aria-label="Permalink to &quot;为什么学&quot;">​</a></h2><ul><li>漏洞分析、恶意代码、协议设计都建立在对数据组织和算法效率的理解之上；</li><li>CTF 中的算法题、密码学中的复杂运算、网络协议的实现都依赖数据结构；</li><li>它是保研、考研、大厂笔试面试的必考内容。</li></ul><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><ul><li>线性表、栈、队列、串</li><li>树与二叉树（含 Huffman、堆）</li><li>图（遍历、最短路径、最小生成树）</li><li>查找（二分、散列表）与排序（各类复杂度）</li><li>复杂度分析（大 O 记号）</li></ul><h2 id="推荐资源" tabindex="-1">推荐资源 <a class="header-anchor" href="#推荐资源" aria-label="Permalink to &quot;推荐资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td>校内教材《数据结构》</td><td>教材</td><td>以课程为主线</td></tr><tr><td>王道考研《数据结构》</td><td>教辅/视频</td><td>体系化梳理 + 真题，考研与期末都好用</td></tr><tr><td>UCB CS61B: Data Structures</td><td>公开课</td><td>英文经典，含大型项目作业</td></tr><tr><td><a href="https://oi-wiki.org/" target="_blank" rel="noreferrer">OI Wiki</a></td><td>知识库</td><td>中文算法百科，查缺补漏</td></tr></tbody></table><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><ul><li>课程设计（大作业）<strong>认真做</strong>，独立完成一遍胜过刷十遍题；</li><li>动手实现核心数据结构（栈、队列、树、图、散列表），别只看不写；</li><li>网安方向不需要竞赛级算法深度，但「会分析复杂度、会选型」是底线要求。</li></ul>',10)])])}const b=a(i,[["render",d]]);export{u as __pageData,b as default};
